`,raw:"",frontmatter:Qe,filepath:"",start:822,id:25,no:26},__clicksContext:null,__preloaded:!1}),uc={},Ye=E(uc),dc=O({get layout(){return Ye.layout},get transition(){return Ye.transition},get class(){return Ye.class},get clicks(){return Ye.clicks},get name(){return Ye.name},get preload(){return Ye.preload},slide:{content:"",revision:"fp4lcc",note:"",title:"What the Lane Conversion Costs",level:1,index:26,noteHTML:`<ul>
